const isLocaleMessageGroup = (
  value: unknown,
): value is Record<string, unknown> =>
  !!value && typeof value === "object" && !Array.isArray(value);

const mergeLocaleMessages = <T extends Record<string, unknown>>(
  base: T,
  extra: Record<string, unknown>,
): T => {
  const mutableBase: Record<string, unknown> = base;
  for (const [key, value] of Object.entries(extra)) {
    if (isLocaleMessageGroup(value)) {
      const current = mutableBase[key];
      mutableBase[key] = mergeLocaleMessages(
        isLocaleMessageGroup(current) ? current : {},
        value,
      );
      continue;
    }
    if (mutableBase[key] === undefined) mutableBase[key] = value;
  }
  return base;
};

